# Final check: verify C% values are exact matches
python3 -c "
# Source values from plan_028 multi_bench_summary.csv
c_pct = {
    'MMLU': 31.3, 'WinoGrande': 30.3, 'TruthfulQA': 29.7,
    'ARC': 26.9, 'GSM8K': 18.9, 'HellaSwag': 17.9
}
paper = {
    'MMLU': 31.3, 'WinoGrande': 30.3, 'TruthfulQA': 29.7,
    'ARC': 26.9, 'GSM8K': 18.9, 'HellaSwag': 17.9
}
for k, v in c_pct.items():
    match = '✅' if v == paper[k] else '❌'
    print(f'{k}: source={v}, paper={paper[k]} {match}')
"
